ALTER POLICY products_staff_read ON public.products USING ((SELECT public.has_capability(auth.uid(),'catalog.view')));
ALTER POLICY products_manage ON public.products USING ((SELECT public.has_capability(auth.uid(),'product.manage'))) WITH CHECK ((SELECT public.has_capability(auth.uid(),'product.manage')));
ALTER POLICY variants_staff_read ON public.product_variants USING ((SELECT public.has_capability(auth.uid(),'catalog.view')));
ALTER POLICY variants_manage ON public.product_variants USING ((SELECT public.has_capability(auth.uid(),'product.manage'))) WITH CHECK ((SELECT public.has_capability(auth.uid(),'product.manage')));
DO $ddl$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.create_stock_reservation(uuid,uuid,integer,timestamp with time zone,text,text,uuid,text,text)'::regprocedure) INTO d; d:=replace(d,'NOT public.has_capability(uid,''stock.reservation.create'')',E'NOT (public.has_capability(uid,''stock.reservation.create'') OR (public.colab_restrita() AND public.has_capability(uid,''kit.manage'') AND _origin=''maleta'' AND EXISTS(SELECT 1 FROM public.kit_cycles c JOIN public.kit_compositions co ON co.cycle_id=c.id JOIN public.kit_composition_items i ON i.composition_id=co.id WHERE c.id::text=_reference AND public.colab_cycle_ok(c.id) AND c.status IN (''rascunho'',''montagem'') AND co.frozen_at IS NULL AND c.origin_location_id=_location_id AND c.consultora_party_id IS NOT DISTINCT FROM _party_id AND i.variant_id=_variant_id AND i.quantity=_quantity AND _idempotency_key=''maleta-conf:''||co.id::text||'':''||i.variant_id::text)))'); EXECUTE d; END $ddl$;